$bytes = [System.IO.File]::ReadAllBytes("$PWD\index.html")
$text = [System.Text.Encoding]::UTF8.GetString($bytes)

$b64 = ''
$jsonBytes = [Convert]::FromBase64String($b64)
$jsonStr = [System.Text.Encoding]::UTF8.GetString($jsonBytes)
$replacements = $jsonStr | ConvertFrom-Json

foreach ($prop in $replacements.psobject.properties) {
    $text = $text.Replace($prop.Name, $prop.Value)
}

# Remove the missing Dakhla ones
$text = [regex]::Replace($text, '(?s)[ \t]*<div class="city-card">\s*<div class="city-card-img-wrap">\s*<img src="images/dakhla/(porte_quartier_espagnol|inifaffen_chyaf|aghylas|desert_ocean|gastronomie_nomade)\.jpg"[^>]+>\s*</div>\s*<h3>.*?</h3>.*?</div>\s*', "")

# Remove the Tajine de poisson food-pill from Essaouira
$text = [regex]::Replace($text, '(?s)[ \t]*<div class="food-pill">\s*<img class="food-pill-img" src="images/essaouira/tajine_poisson\.jpg"[^>]+>\s*</div>\s*<div>.*?</div>\s*</div>\s*', "")

$utf8NoBom = New-Object System.Text.UTF8Encoding $false
[System.IO.File]::WriteAllText("$PWD\index.html", $text, $utf8NoBom)
Write-Output "Done Dakhla + Tajine removals!"
